要点：{{start.keyPoints}}
【产出 JSON】{"title":"标题","positioning":"一句话定位","narration":"全片完整口播（可分段，用 | 分句）","sections":[{"role":"段落作用","keyPoint":"本段要点","narration":"本段口播句"}],"structureNote":"结构说明"}
